import pandas as pd,gzip,numpy as np
def mat(f):
    lines=[];on=False
    for l in gzip.open(f'studies/data/raw/{f}_series_matrix.txt.gz','rt'):
        if l.startswith('!series_matrix_table_begin'): on=True; continue
        if l.startswith('!series_matrix_table_end'): break
        if on: lines.append(l)
    from io import StringIO
    return pd.read_csv(StringIO(''.join(lines)),sep='\t',index_col=0)
